scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 하단의 1번 버튼을 클릭 후 4번 버튼을 클릭한다.
    //1. After running the sample, click button 1 at the bottom and click button 4.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    //Verify 1. gridView가 필터링되어 지고 알림창에 '사사'값이 보여진다.
    //1. The gridView is filtered, and a 'yes' value is displayed in the notification window.
    WebSquare.wUnit.addCommand("assert", "log == '사사'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 3번 버튼 클릭 후 4번 버튼을 클릭한다.
    //2. Click button 3 and then button 4.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 알림창에 '10299'값이 보여진다.(필터링되어 숨겨진 index값의 col값을 가져온다.) (이전에는 기능이 없었음)
    //2. The '10299' value will be displayed in the notification window (it will be filtered to get the col value of the hidden index value). (Previously no functionality)
    WebSquare.wUnit.addCommand("assert", "log", "10299");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
